class Solution {
    public int maxSizeSlices(int[] slices) {
        int n = slices.length / 3;
        List<Integer> list = new ArrayList<>();
        for (int s : slices) list.add(s);
        return dfs(list, n);
    }
    private int dfs(List<Integer> arr, int k) {
        if (k == 0) return 0;
        if (arr.size() < 3 * k - 2) return Integer.MIN_VALUE / 2;
        int best = Integer.MIN_VALUE / 2;
        int m = arr.size();
        for (int i = 0; i < m; i++) {
            List<Integer> nxt = new ArrayList<>();
            if (i == 0) {
                for (int j = 2; j < m - 1; j++) nxt.add(arr.get(j));
            } else if (i == m - 1) {
                for (int j = 1; j < i - 1; j++) nxt.add(arr.get(j));
            } else {
                for (int j = 0; j < i - 1; j++) nxt.add(arr.get(j));
                for (int j = i + 2; j < m; j++) nxt.add(arr.get(j));
            }
            best = Math.max(best, arr.get(i) + dfs(nxt, k - 1));
        }
        return best;
    }
}

