var maxSizeSlices = function(slices) {
    const n = slices.length / 3;
    function dfs(arr, k) {
        if (k === 0) return 0;
        if (arr.length < 3 * k - 2) return -Infinity;
        let best = -Infinity;
        const m = arr.length;
        for (let i = 0; i < m; i++) {
            let nxt;
            if (i === 0) nxt = arr.slice(2, m - 1);
            else if (i === m - 1) nxt = arr.slice(1, i - 1);
            else nxt = arr.slice(0, i - 1).concat(arr.slice(i + 2));
            best = Math.max(best, arr[i] + dfs(nxt, k - 1));
        }
        return best;
    }
    return dfs(slices, n);
};

