class Solution {
    private int solve(int[] a, int k) {
        int m = a.length;
        int[][] dp = new int[m + 1][k + 1];
        for (int i = 1; i <= m; i++)
            for (int j = 1; j <= k; j++)
                dp[i][j] = Math.max(dp[i-1][j],
                        (i >= 2 ? dp[i-2][j-1] : 0) + a[i-1]);
        return dp[m][k];
    }
    public int maxSizeSlices(int[] slices) {
        int k = slices.length / 3;
        int[] a = new int[slices.length - 1];
        int[] b = new int[slices.length - 1];
        System.arraycopy(slices, 1, a, 0, a.length);
        System.arraycopy(slices, 0, b, 0, b.length);
        return Math.max(solve(a, k), solve(b, k));
    }
}

